"""Regenerate questionnaire and empty standard result forms from the actual engine."""
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "skills/software-process-audit/scripts"))
import audit


def main():
    criteria = audit.catalog(audit.CONTROLS)
    lines = ["# Software Assurance Auditor: complete questionnaire", "",
             "Generated by `python scripts/export_audit_templates.py`. Standard " + criteria["standard_version"] + ".",
             "", "24 criteria, 72 separately assessed checkpoints. Each checkpoint uses the 0–4 rubric; unknowns remain unscored. The challenge is a review method, not permission to run code.", "",
             "## Scoring rubric", "", "| Score | Interpretation |", "|---|---|"]
    lines += [f"| {key} | {value} |" for key, value in criteria["scoring_rubric"].items()]
    for control in criteria["controls"]:
        lines += ["", f"## {control['id']} — {control['criterion']}", "",
                  f"Stage: {control['stage']}. Weight per checkpoint: {control['weight']}. Successful execution required for scores 3/4: {control['successful_execution_required_for_support']}.", "",
                  control["audit_question"], "", "| ID | Checkpoint |", "|---|---|"]
        lines += [f"| {item['id']} | {item['question']} |" for item in control["checkpoints"]]
        lines += ["", "Verification approach: " + control["challenge"]]
    lines += ["", "## Stage handoffs", "", "| Gate | From | To | Required criteria |", "|---|---|---|---|"]
    lines += [f"| {g['id']} | {g['from']} | {g['to']} | {', '.join(g['required_controls'])} |" for g in criteria["stage_gates"]]
    docs = ROOT / "docs"
    docs.mkdir(exist_ok=True)
    (docs / "AUDIT_QUESTIONNAIRE.md").write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")
    examples = ROOT / "examples/software-audit"
    examples.mkdir(parents=True, exist_ok=True)
    manifest = audit.new_manifest("UNASSESSED-SNAPSHOT", "Blank standard form; no project has been audited")
    report = audit.evaluate(manifest, ROOT, "UNASSESSED-SNAPSHOT")
    (examples / "blank-review.json").write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8", newline="\n")
    (examples / "blank-report.json").write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8", newline="\n")
    (examples / "blank-report.md").write_text(audit.markdown(report), encoding="utf-8", newline="\n")
    print("Exported complete questionnaire and blank report template (72 checkpoint rows).")


if __name__ == "__main__":
    main()
